/// <summary>
/// CB790_DiscountClaim
/// </summary>
[ExtensionOf(classStr(GUPDiscountClaimProcess))]
final class METGUPDiscountClaimProcess_Extension
{
    // Bug 217709: CB789 - Financial dimension combination error while posting the vendor claim invoice
    private DimensionDefault custInvoiceJourDefaultDimension;
    
}

Method.Source:
    /// <summary>
    /// Change the claimFeeCalculation loop from GUPDiscountVendorClaimFeeSetup to custom table METClaimSetup
    /// </summary>
    /// <param name = "_discountClaimId"></param>
    protected void calculateClaimPercentFee(GUPDiscountClaimId _discountClaimId)
    {           
        // std call won't create anything as there won't be any records in GUPDiscountVendorClaimFeeSetup 
        next calculateClaimPercentFee(_discountClaimId);

        GUPDiscountClaimTransaction             claimTrans;
        GUPDiscountClaim                        discountClaim;
        METClaimSetup                           claimSetupGroup;
        GUPDiscountVendorClaimFeeCalculation    claimFeeCalculation;

        select sum(Amount) from claimTrans
            where claimTrans.DiscountClaimId == _discountClaimId;

        // The % fee is applied to discount claims raised if the combination of site/supplier/component has a % fee attached in METClaimSetup
        while select Supplier, Component from claimSetupGroup
                join METInventSiteId, CurrencyCode from discountClaim
                group by claimSetupGroup.Supplier, claimSetupGroup.Component, discountClaim.METInventSiteId
                where discountClaim.VendorAccount    == claimSetupGroup.Supplier
                   && discountClaim.METComponent     == claimSetupGroup.Component
                   && discountClaim.DiscountClaimId  == _discountClaimId
        {
            // Supplier Claim Setup, where Site = blank, will signify that the values for supplier/claim type and fee apply to all sites in the Legal Entity.
            // This will reduce the number of rows of data required for ALM as all suppliers have the same claim type in each site and they do not use the Admin Fee (Food only)
            METClaimSetup claimSetup = METClaimSetup::findByComponentSupplier(
                                        claimSetupGroup.Component,
                                        claimSetupGroup.Supplier,
                                        discountClaim.METInventSiteId);
            
            if (claimSetup)
            {
                claimFeeCalculation.clear();
                claimFeeCalculation.DiscountClaimId = _discountClaimId;
                claimFeeCalculation.FeeSetupRecId = claimSetup.RecId;
            
                // admin fee amount is excluding GST and TaxItemGroup set to GST
                claimFeeCalculation.Amount = claimTrans.Amount * (claimSetup.AdminFee * 0.01);
                // Claim related amounts to be rounded to 2 decimal places
                claimFeeCalculation.Amount = round(claimFeeCalculation.Amount, Currency::roundingPrecisionAdjusted(discountClaim.CurrencyCode));
                claimFeeCalculation.VendorClaimInvoice = curInvoiceId;

                // force to percentage
                claimFeeCalculation.CalcType = GUPDiscountClaimCalcType::Percent;
                // GST for journal as per standard
                claimFeeCalculation.TaxItemGroup = METConstants::taxGroupGST;
                claimFeeCalculation.FeeAccount = claimSetup.FeeAccount;

                // only create if amount > 0
                if (claimFeeCalculation.Amount)
                {
                    claimFeeCalculation.insert();
                }                
            }
        }
    }

    /// <summary>
    /// Bug 217709: CB789 - Financial dimension combination error while posting the vendor claim invoice
    /// Set missing financial dimensions in the vendor invoice journal Discount claim accrual - Reversal
    /// Because of the account structures configured, fin dim are required
    /// </summary>
    /// <param name = "_claimTrans"><c>GUPDiscountClaimTransaction</c> record</param>
    /// <returns><c>LedgerJournalTrans</c> record</returns>
    protected LedgerJournalTrans initFromGUPDiscountClaimTransaction(GUPDiscountClaimTransaction _claimTrans)
    {
        LedgerJournalTrans ledgerjournalTrans = next initFromGUPDiscountClaimTransaction(_claimTrans);

        ledgerJournalTrans.LedgerDimension = LedgerDimensionFacade::serviceCreateLedgerDimension(_claimTrans.LedgerAccount, _claimTrans.DefaultDimension);

        return ledgerjournalTrans;
    }

    /// <summary>
    /// Bug 217709: CB789 - Financial dimension combination error while posting the vendor claim invoice
    /// Retrieve the sales invoice header default dimension
    /// </summary>
    /// <param name = "_vendTable"><c>VendTable</c> record</param>
    /// <param name = "_discountClaim"><c>GUPDiscountClaim</c> record</param>
    public void initValue(VendTable _vendTable, GUPDiscountClaim _discountClaim)
    {
        next initValue(_vendTable, _discountClaim);

        CustInvoiceJour custInvoiceJour;
        GUPDiscountClaim discountClaim;

        // get default dim from sales invoice header
        select DefaultDimension from custInvoiceJour 
                         exists join discountClaim
                               where discountClaim.DiscountClaimId == _discountClaim.discountClaimId
                                  && custInvoiceJour.InvoiceId     == discountClaim.SalesInvoice;

        custInvoiceJourDefaultDimension = custInvoiceJour.DefaultDimension;
    }

    /// <summary>
    /// Bug 217709: CB789 - Financial dimension combination error while posting the vendor claim invoice
    /// For the ledger line type, add the customer invoice header default dimensions
    /// </summary>
    /// <param name = "_feeCalc"><c>GUPDiscountVendorClaimFeeCalculation</c> record</param>
    /// <returns><c>LedgerJournalTrans</c> record</returns>
    protected LedgerJournalTrans initFromGUPDiscountVendorClaimFeeCalculation(GUPDiscountVendorClaimFeeCalculation _feeCalc)
    {
        LedgerJournalTrans ledgerjournalTrans = next initFromGUPDiscountVendorClaimFeeCalculation(_feeCalc);

        ledgerJournalTrans.LedgerDimension = LedgerDimensionFacade::serviceCreateLedgerDimension(_feeCalc.FeeAccount, custInvoiceJourDefaultDimension);
        
        return ledgerjournalTrans;
    }

    /// <summary>
    /// Bug 217709: CB789 - Financial dimension combination error while posting the vendor claim invoice
    /// For the vendor line type, set the default dimension from the customer invoice header
    /// </summary>
    /// <param name = "_claimAmount">Claim amount</param>
    /// <returns><c>LedgerJournalTrans</c> record</returns>
    protected LedgerJournalTrans createClaimLedgerJournalTransVend(Amount _claimAmount)
    {
        LedgerJournalTrans ledgerjournalTrans = next createClaimLedgerJournalTransVend(_claimAmount);

        ledgerJournalTrans.DefaultDimension = custInvoiceJourDefaultDimension;

        return ledgerjournalTrans;
    }
